"""TK6B.1: exact finite positive restriction-semigroup audit.

For a finite branching closure, collapse the two outer-conjugate Spin(10)
parents because they have identical Spin(9) restrictions.  The remaining
columns are the multiplicity-free D5 -> B4 interlacing packets.  This module
constructs their nonnegative integer semigroup and audits:

* the exact rational cone and its irredundant facet inequalities;
* total unimodularity, with an explicit minor when it fails;
* the ambient lattice generated by the packet columns;
* the Hilbert basis and saturation of the semigroup, using PyNormaliz; and
* the cumulative HFT targets against every facet and by exact integral
  packet witnesses.

The calculation is baseline-free.  It imports no protected SO(10) completion.
PyNormaliz is an optional exact backend; pass ``--normaliz-path`` when it is
installed outside the active Sage environment.
"""

import argparse
import itertools
import sys
import time
from collections import Counter

from sage.all import MixedIntegerLinearProgram, Polyhedron, ZZ, matrix
from sage.numerical.mip import MIPSolverException

import finite_cross_section as cross
from trajectory_kernel import kernel_lattice
from trajectory_kernel import milp_certification


def packet_matrix(domain):
    """Return the exact unoriented branching-packet matrix for ``domain``."""
    weights = domain["weights"]
    parents = domain["parents"]
    tables = domain["branch_tables"]
    return matrix(
        ZZ,
        len(weights),
        len(parents),
        lambda row, column: tables[parents[column]].get(weights[row], 0),
    )


def reference_matrix(domain):
    """Return the all-chiral square packet submatrix, ordered by top weight."""
    weights = domain["weights"]
    tables = domain["branch_tables"]
    parents = tuple(
        cross.select_parent(weight, policy="chiral") for weight in weights
    )
    return parents, matrix(
        ZZ,
        len(weights),
        len(weights),
        lambda row, column: tables[parents[column]].get(weights[row], 0),
    )


def packet_structure_diagnostics(domain, packets):
    """Verify that the columns are the full unoriented interlacing packets."""
    weights = domain["weights"]
    parents = domain["parents"]
    expected_parents = tuple(
        sorted(
            parent
            for weight in weights
            for parent in cross.positive_chirality_parent_family(weight)
        )
    )
    reference_parents, reference = reference_matrix(domain)
    determinant = reference.det()
    columns = tuple(
        tuple(int(value) for value in packets.column(index))
        for index in range(packets.ncols())
    )
    return {
        "full_unoriented_parent_family": parents == expected_parents,
        "all_entries_binary": all(value in (0, 1) for value in packets.list()),
        "all_columns_nonzero": all(any(column) for column in columns),
        "all_columns_distinct": len(set(columns)) == len(columns),
        "top_weights_exact": all(
            cross.top_b4_weight(parent) in weights for parent in parents
        ),
        "reference_parents": reference_parents,
        "reference_determinant": int(determinant),
        "ambient_lattice_is_full": abs(determinant) == 1,
        "rank": packets.rank(),
        "nullity": packets.ncols() - packets.rank(),
    }


def _determinant_3(columns):
    """Determinant of a 3-by-3 matrix supplied as three column triples."""
    left, middle, right = columns
    return (
        left[0] * (middle[1] * right[2] - middle[2] * right[1])
        - middle[0] * (left[1] * right[2] - left[2] * right[1])
        + right[0] * (left[1] * middle[2] - left[2] * middle[1])
    )


def find_binary_nonunimodular_minor(packets):
    """Find an exact determinant-two 3-by-3 minor of a binary matrix.

    A returned certificate disproves total unimodularity.  Returning ``None``
    means only that this bounded minor search found no certificate; it is not a
    proof of total unimodularity.
    """
    if any(value not in (0, 1) for value in packets.list()):
        raise ValueError("The optimized minor search requires a binary matrix")

    patterns = tuple(itertools.product((0, 1), repeat=3))
    bad_pattern_sets = tuple(
        (pattern_set, _determinant_3(pattern_set))
        for pattern_set in itertools.combinations(patterns, 3)
        if abs(_determinant_3(pattern_set)) > 1
    )
    for rows in itertools.combinations(range(packets.nrows()), 3):
        first_column = {}
        for column in range(packets.ncols()):
            pattern = tuple(int(packets[row, column]) for row in rows)
            first_column.setdefault(pattern, column)
        for pattern_set, determinant in bad_pattern_sets:
            if all(pattern in first_column for pattern in pattern_set):
                columns = tuple(first_column[pattern] for pattern in pattern_set)
                minor = matrix(
                    ZZ,
                    3,
                    3,
                    lambda row, column: packets[rows[row], columns[column]],
                )
                if minor.det() != determinant:
                    raise ValueError("Minor certificate determinant mismatch")
                return {
                    "rows": rows,
                    "columns": columns,
                    "matrix": tuple(
                        tuple(int(value) for value in row)
                        for row in minor.rows()
                    ),
                    "determinant": int(determinant),
                }
    return None


def packet_rays(packets):
    """Return packet columns as immutable integer ray vectors."""
    return tuple(
        tuple(int(value) for value in packets.column(column))
        for column in range(packets.ncols())
    )


def cone_diagnostics(packets):
    """Construct the exact PPL cone and its irredundant H-representation."""
    rays = packet_rays(packets)
    cone = Polyhedron(rays=rays, base_ring=ZZ, backend="ppl")
    inequalities = tuple(
        tuple(int(value) for value in inequality)
        for inequality in cone.inequalities_list()
    )
    equations = tuple(
        tuple(int(value) for value in equation)
        for equation in cone.equations_list()
    )
    if any(inequality[0] for inequality in inequalities):
        raise ValueError("A homogeneous packet cone returned an affine facet")
    support_sizes = Counter(
        sum(value != 0 for value in inequality[1:])
        for inequality in inequalities
    )
    maximum_coefficients = Counter(
        max((abs(value) for value in inequality[1:]), default=0)
        for inequality in inequalities
    )
    return {
        "cone": cone,
        "rays": rays,
        "dimension": cone.dim(),
        "extreme_rays": cone.n_rays(),
        "facets": cone.n_inequalities(),
        "equations": equations,
        "inequalities": inequalities,
        "support_size_histogram": dict(sorted(support_sizes.items())),
        "maximum_coefficient_histogram": dict(sorted(maximum_coefficients.items())),
    }


def _load_normaliz(normaliz_path=None):
    """Load the optional exact Normaliz backend."""
    if normaliz_path is not None and normaliz_path not in sys.path:
        sys.path.insert(0, normaliz_path)
    try:
        from PyNormaliz import Cone
    except ImportError as error:
        raise RuntimeError(
            "PyNormaliz is required for the Hilbert-basis audit. Install the "
            "dependency listed in requirements-tk6b.txt or pass "
            "--normaliz-path."
        ) from error
    return Cone


def hilbert_basis_diagnostics(rays, normaliz_path=None):
    """Compute the exact Hilbert basis and integral-closure diagnostics."""
    NormalizCone = _load_normaliz(normaliz_path)
    normaliz_cone = NormalizCone(cone=[list(ray) for ray in rays])
    hilbert_basis = tuple(
        tuple(int(value) for value in item)
        for item in normaliz_cone.HilbertBasis()
    )
    ray_set = set(rays)
    basis_set = set(hilbert_basis)
    return {
        "normaliz_cone": normaliz_cone,
        "rank": int(normaliz_cone.Rank()),
        "extreme_rays": len(normaliz_cone.ExtremeRays()),
        "hilbert_basis": hilbert_basis,
        "hilbert_basis_size": len(hilbert_basis),
        "integrally_closed": bool(normaliz_cone.IsIntegrallyClosed()),
        "missing_packet_generators": tuple(sorted(ray_set - basis_set)),
        "additional_hilbert_generators": tuple(sorted(basis_set - ray_set)),
        "hilbert_basis_equals_packets": basis_set == ray_set,
    }


def target_vector(domain, level):
    """Return one cumulative HFT target in the finite B4 row basis."""
    table = cross.character_coefficients(domain["cumulative"][level])
    return tuple(int(table.get(weight, 0)) for weight in domain["weights"])


def facet_target_diagnostics(target, inequalities):
    """Evaluate an integral target against every exact cone facet."""
    slacks = tuple(
        sum(
            coefficient * value
            for coefficient, value in zip(inequality[1:], target)
        )
        for inequality in inequalities
    )
    positive_slacks = tuple(value for value in slacks if value > 0)
    return {
        "slacks": slacks,
        "in_cone": all(value >= 0 for value in slacks),
        "violated_facets": sum(value < 0 for value in slacks),
        "tight_facets": sum(value == 0 for value in slacks),
        "minimum_slack": min(slacks, default=0),
        "minimum_positive_slack": min(positive_slacks, default=None),
    }


def integral_packet_witness(packets, target):
    """Find and exactly verify one nonnegative integral packet decomposition."""
    program = MixedIntegerLinearProgram(maximization=False, solver="GLPK")
    coefficients = program.new_variable(integer=True, nonnegative=True)
    for row in range(packets.nrows()):
        expression = program.sum(
            int(packets[row, column]) * coefficients[column]
            for column in range(packets.ncols())
            if packets[row, column]
        )
        program.add_constraint(expression == int(target[row]))
    objective = program.sum(
        coefficients[column] for column in range(packets.ncols())
    )
    program.set_objective(objective)
    try:
        optimum = milp_certification.checked_integer(
            program.solve(), "packet-witness objective"
        )
    except MIPSolverException as error:
        return {
            "feasible": False,
            "message": str(error),
            "coefficients": (),
            "exact": False,
        }

    values = program.get_values(coefficients)
    witness = tuple(
        milp_certification.checked_value(
            values, column, "packet multiplicity"
        )
        for column in range(packets.ncols())
    )
    reconstructed = tuple(
        sum(
            int(packets[row, column]) * witness[column]
            for column in range(packets.ncols())
        )
        for row in range(packets.nrows())
    )
    exact = reconstructed == tuple(target)
    nonnegative = all(value >= 0 for value in witness)
    objective_exact = sum(witness) == optimum
    if not (exact and nonnegative and objective_exact):
        raise ValueError("MILP packet witness failed exact integer verification")
    return {
        "feasible": True,
        "message": None,
        "coefficients": witness,
        "exact": exact,
        "nonnegative": nonnegative,
        "objective": optimum,
        "nonzero_packets": sum(value != 0 for value in witness),
    }


def analyze_restriction_semigroup(
    max_level=11, normaliz_path=None, skip_normaliz=False
):
    """Run the complete baseline-free TK6B.1 finite audit."""
    domain = kernel_lattice.build_finite_domain(max_level)
    packets = packet_matrix(domain)
    structure = packet_structure_diagnostics(domain, packets)
    non_tu_minor = find_binary_nonunimodular_minor(packets)
    cone = cone_diagnostics(packets)
    hilbert = None if skip_normaliz else hilbert_basis_diagnostics(
        cone["rays"], normaliz_path=normaliz_path
    )
    targets = {}
    for level in range(1, max_level + 1):
        target = target_vector(domain, level)
        facets = facet_target_diagnostics(target, cone["inequalities"])
        witness = integral_packet_witness(packets, target)
        targets[level] = {
            "target": target,
            "support": sum(value != 0 for value in target),
            "multiplicity_mass": sum(target),
            "facets": facets,
            "witness": witness,
        }
    return {
        "max_level": max_level,
        "domain": domain,
        "packets": packets,
        "structure": structure,
        "non_tu_minor": non_tu_minor,
        "cone": cone,
        "hilbert": hilbert,
        "targets": targets,
        "all_targets_in_cone": all(
            item["facets"]["in_cone"] for item in targets.values()
        ),
        "all_targets_have_integral_witness": all(
            item["witness"]["feasible"] and item["witness"]["exact"]
            for item in targets.values()
        ),
    }


def _histogram_range(histogram):
    if not histogram:
        return "none"
    return f"{min(histogram)}..{max(histogram)}"


def run_analysis(
    max_level=11, normaliz_path=None, skip_normaliz=False, verbose=False
):
    """Print the reproducible TK6B.1 audit."""
    print("=" * 104)
    print("TK6B.1 — POSITIVE D5 -> B4 RESTRICTION SEMIGROUP")
    print("=" * 104)
    started = time.time()
    result = analyze_restriction_semigroup(
        max_level=max_level,
        normaliz_path=normaliz_path,
        skip_normaliz=skip_normaliz,
    )
    structure = result["structure"]
    cone = result["cone"]
    minor = result["non_tu_minor"]
    hilbert = result["hilbert"]

    print("\nFinite unoriented packet system:")
    print(
        "  B4 rows / D5 packet columns: "
        f"{result['packets'].nrows()} / {result['packets'].ncols()}"
    )
    print(f"  Rank / kernel rank: {structure['rank']} / {structure['nullity']}")
    print(
        "  Complete outer-orbit parent family: "
        f"{structure['full_unoriented_parent_family']}"
    )
    print(f"  Binary multiplicity-free columns: {structure['all_entries_binary']}")
    print(
        "  Unimodular reference-section determinant: "
        f"{structure['reference_determinant']}"
    )

    print("\nTotal-unimodularity audit:")
    if minor is None:
        print(
            "  No determinant-two 3x3 minor found; total unimodularity "
            "remains unclassified."
        )
    else:
        row_labels = tuple(
            result["domain"]["weights"][index] for index in minor["rows"]
        )
        parent_labels = tuple(
            result["domain"]["parents"][index]
            for index in minor["columns"]
        )
        print("  Totally unimodular: False")
        print(f"  Exact minor determinant: {minor['determinant']}")
        print(f"  B4 rows: {row_labels}")
        print(f"  D5 columns: {parent_labels}")
        print(f"  Minor: {minor['matrix']}")

    print("\nExact rational cone:")
    print(
        "  Dimension / extreme rays / irredundant facets: "
        f"{cone['dimension']} / {cone['extreme_rays']} / {cone['facets']}"
    )
    print(f"  Linear equations: {len(cone['equations'])}")
    print(
        "  Facet support-size range: "
        f"{_histogram_range(cone['support_size_histogram'])}"
    )
    print(
        "  Facet max-|coefficient| range: "
        f"{_histogram_range(cone['maximum_coefficient_histogram'])}"
    )
    if verbose:
        print(f"  Facet support histogram: {cone['support_size_histogram']}")
        print(f"  Facet coefficient histogram: {cone['maximum_coefficient_histogram']}")

    print("\nExact integer semigroup:")
    if hilbert is None:
        print("  Hilbert-basis audit: SKIPPED")
    else:
        print(f"  Hilbert basis size: {hilbert['hilbert_basis_size']}")
        print(
            "  Hilbert basis equals packet columns: "
            f"{hilbert['hilbert_basis_equals_packets']}"
        )
        print(f"  Integrally closed / saturated: {hilbert['integrally_closed']}")
        print(
            "  Additional Hilbert generators (holes): "
            f"{len(hilbert['additional_hilbert_generators'])}"
        )

    print("\nCumulative HFT target audit:")
    print(
        "  level  support  mass     tight facets  in cone  "
        "witness support/total  exact"
    )
    for level, item in result["targets"].items():
        witness = item["witness"]
        packet_support = witness.get("nonzero_packets", "-")
        packet_total = witness.get("objective", "-")
        packet_count = f"{packet_support}/{packet_total}"
        print(
            f"  {level:<6} {item['support']:<8} {item['multiplicity_mass']:<8} "
            f"{item['facets']['tight_facets']:<13} "
            f"{str(item['facets']['in_cone']):<8} {packet_count:<22} "
            f"{witness['exact']}"
        )
    if verbose:
        final_level = max(result["targets"])
        final_target = result["targets"][final_level]["target"]
        tight_inequalities = tuple(
            inequality
            for inequality in cone["inequalities"]
            if sum(
                coefficient * value
                for coefficient, value in zip(inequality[1:], final_target)
            ) == 0
        )
        print(f"\n  Tight level-{final_level} facet functionals:")
        for index, inequality in enumerate(tight_inequalities, start=1):
            terms = tuple(
                (result["domain"]["weights"][row], coefficient)
                for row, coefficient in enumerate(inequality[1:])
                if coefficient
            )
            print(f"    {index}: {terms}")

    checks = (
        structure["full_unoriented_parent_family"]
        and structure["all_entries_binary"]
        and structure["all_columns_nonzero"]
        and structure["all_columns_distinct"]
        and structure["ambient_lattice_is_full"]
        and minor is not None
        and cone["dimension"] == result["packets"].nrows()
        and cone["extreme_rays"] == result["packets"].ncols()
        and result["all_targets_in_cone"]
        and result["all_targets_have_integral_witness"]
        and (
            hilbert is None
            or (
                hilbert["integrally_closed"]
                and hilbert["hilbert_basis_equals_packets"]
                and not hilbert["additional_hilbert_generators"]
            )
        )
    )
    print("-" * 104)
    print("Protected SO(10) baseline imported: NO")
    print(f"TK6B.1 finite audit: {'PASS' if checks else 'FAIL'}")
    print(f"Runtime: {time.time() - started:.3f}s")
    result["all_checks"] = checks
    return result


def run_self_test(normaliz_path=None, skip_normaliz=False):
    """Run exact synthetic tests of the cone, minor and Hilbert routines."""
    nonnormal = matrix(
        ZZ,
        (
            (1, 1, 0),
            (1, 0, 1),
            (0, 1, 1),
        ),
    )
    minor = find_binary_nonunimodular_minor(nonnormal)
    if minor is None or abs(minor["determinant"]) != 2:
        raise AssertionError("Failed to recover the determinant-two minor")
    cone = cone_diagnostics(nonnormal)
    if cone["dimension"] != 3 or cone["extreme_rays"] != 3:
        raise AssertionError("Synthetic cone diagnostics failed")

    if not skip_normaliz:
        hilbert = hilbert_basis_diagnostics(cone["rays"], normaliz_path)
        if hilbert["integrally_closed"]:
            raise AssertionError("Synthetic even-sum semigroup should not be saturated")
        if hilbert["additional_hilbert_generators"] != ((1, 1, 1),):
            raise AssertionError("Synthetic Hilbert holes were not recovered")

    print("TK6B.1 RESTRICTION-SEMIGROUP SELF-TEST")
    print("  Determinant-two minor: PASS")
    print("  Exact rational cone: PASS")
    print(
        "  Synthetic nonnormal Hilbert basis: "
        f"{'SKIPPED' if skip_normaliz else 'PASS'}"
    )
    print("  Protected SO(10) baseline imported: NO")
    return True


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Audit the finite positive D5 -> B4 restriction semigroup"
    )
    parser.add_argument("--max-level", type=int, default=11)
    parser.add_argument("--normaliz-path")
    parser.add_argument("--skip-normaliz", action="store_true")
    parser.add_argument("--self-test", action="store_true")
    parser.add_argument("--verbose", action="store_true")
    args = parser.parse_args(argv)

    try:
        if args.self_test:
            run_self_test(
                normaliz_path=args.normaliz_path,
                skip_normaliz=args.skip_normaliz,
            )
            return 0
        result = run_analysis(
            max_level=args.max_level,
            normaliz_path=args.normaliz_path,
            skip_normaliz=args.skip_normaliz,
            verbose=args.verbose,
        )
    except Exception as error:
        print(f"TK6B.1 FAILED: {error}", file=sys.stderr)
        return 1
    return 0 if result["all_checks"] else 1


if __name__ == "__main__":
    raise SystemExit(main())
